\set ON_ERROR_STOP on
set timezone='UTC';
create schema message_send_test;
create function message_send_test.id(n integer) returns uuid language sql immutable as $$select ('99950000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create table message_send_test.workspace(value jsonb);
create table message_send_test.cases(name text primary key,request jsonb,response jsonb);
grant usage on schema message_send_test to authenticated;
grant select,insert on all tables in schema message_send_test to authenticated;
insert into auth.users(id,email) select message_send_test.id(n),'message-send-'||n||'@example.test' from generate_series(1,2)n;
select set_config('request.jwt.claim.sub',message_send_test.id(1)::text,false);
set role authenticated;
insert into message_send_test.workspace select public.mobile_create_team_workspace(jsonb_build_object('version',2,'userId',auth.uid(),'requestNonce',message_send_test.id(10),'value',jsonb_build_object('name','Message Team','code','MS-12345','location','Church','callTime','09:00:00','rehearsalTime','08:00:00')))->'workspace';
reset role;
create function message_send_test.channel() returns uuid language sql stable as $$select(value->>'channelId')::uuid from message_send_test.workspace$$;
create function message_send_test.member() returns uuid language sql stable as $$select(value->>'memberId')::uuid from message_send_test.workspace$$;
create function message_send_test.capture(label text,n integer,body text) returns void language plpgsql as $$declare proof record;request jsonb;begin
 select * into proof from public.send_message_once(message_send_test.channel(),message_send_test.id(n),body);
 select jsonb_build_object('version',2,'userId',auth.uid(),'teamId',tm.team_id,'memberId',tm.id,'memberCreatedAt',tm.created_at,'channelId',message_send_test.channel(),'requestNonce',message_send_test.id(n),'body',body) into request from public.team_members tm where tm.id=message_send_test.member();
 insert into message_send_test.cases values(label,request,jsonb_build_object('version',2,'request',request,'status','confirmed','message',jsonb_build_object('id',proof.id,'createdAt',proof.created_at)));
end$$;
create function message_send_test.denied(channel uuid,n integer,body text,expected text) returns void language plpgsql as $$declare rejected boolean:=false;begin begin perform public.send_message_once(channel,message_send_test.id(n),body);exception when others then if sqlstate=expected then rejected:=true;else raise;end if;end;assert rejected,'Expected denied message send';end$$;
insert into auth.users(id,email) values(message_send_test.id(3),'direct-third@example.test');
insert into public.team_members(id,team_id,profile_id,role,status) select message_send_test.id(n+10),(value->>'teamId')::uuid,message_send_test.id(n),'member','active' from message_send_test.workspace cross join generate_series(2,3)n;
update public.team_members set role='admin' where id=message_send_test.id(13);
create schema group_test;
create table group_test.cases(name text primary key,request jsonb not null,receipt jsonb not null);
create table group_test.pending(name text primary key,request jsonb not null);
grant usage on schema group_test to authenticated;
grant select,insert on all tables in schema group_test to authenticated;
create function group_test.channel() returns uuid language sql stable as $$select(receipt->>'channelId')::uuid from group_test.cases where name='create'$$;
create function group_test.request(n integer,operation text,target_user integer default 2) returns jsonb language plpgsql as $$declare result jsonb;v_member uuid;v_channel jsonb;v_target jsonb;v_join jsonb;begin
 select jsonb_build_object('version',2,'userId',auth.uid(),'teamId',a.team_id,'memberId',a.id,'memberCreatedAt',a.created_at,'requestNonce',message_send_test.id(n),'operation',operation),a.id into result,v_member from public.team_members a where a.profile_id=auth.uid();
 if operation='create' then return result||jsonb_build_object('value',jsonb_build_object('name','Choir group'));end if;
 select jsonb_build_object('id',id,'teamId',team_id,'name',name,'createdBy',created_by,'createdAt',created_at) into v_channel from public.message_channels where id=group_test.channel();
 select jsonb_build_object('memberId',id,'profileId',profile_id,'status',status,'createdAt',created_at) into v_target from public.team_members where profile_id=message_send_test.id(target_user);
 select jsonb_build_object('id',id,'channelId',channel_id,'memberId',team_member_id,'createdAt',created_at) into v_join from public.message_channel_members where channel_id=group_test.channel() and team_member_id=case when operation='leave' then v_member else(v_target->>'memberId')::uuid end;
 result:=result||jsonb_build_object('channel',v_channel,'baseJoin',case when operation='add' then null else v_join end);if operation in('add','remove') then result:=result||jsonb_build_object('target',v_target);end if;return result;
end$$;
create function group_test.capture(label text,request jsonb) returns jsonb language plpgsql as $$declare receipt jsonb;begin receipt:=public.mobile_apply_group_channel(request);insert into group_test.cases values(label,request,receipt);return receipt;end$$;
create function group_test.denied(request jsonb,expected text) returns void language plpgsql as $$declare rejected boolean:=false;begin begin perform public.mobile_apply_group_channel(request);exception when others then if sqlstate=expected then rejected:=true;else raise;end if;end;assert rejected,'Expected group denial';end$$;
set role authenticated;
select group_test.capture('create',group_test.request(100,'create'));
select group_test.capture('add-member',group_test.request(101,'add'));
select group_test.capture('remove-member',group_test.request(102,'remove'));
select group_test.capture('readd-member',group_test.request(103,'add'));
do $$declare saved record;begin select * into saved from group_test.cases where name='remove-member';assert public.mobile_apply_group_channel(saved.request)=saved.receipt,'Old remove receipt changed';assert exists(select 1 from public.message_channel_members where channel_id=group_test.channel() and team_member_id=message_send_test.id(12)),'Old remove deleted readd';end$$;
select group_test.denied(jsonb_set((select request from group_test.cases where name='create'),'{value,name}','"Changed"'),'22023');
insert into group_test.pending values('replace-join',group_test.request(150,'remove'));
reset role;
delete from public.message_channel_members where channel_id=group_test.channel() and team_member_id=message_send_test.id(12);
insert into public.message_channel_members(channel_id,team_member_id) values(group_test.channel(),message_send_test.id(12));
set role authenticated;
select group_test.capture('replaced-join-conflict',(select request from group_test.pending where name='replace-join'));
select group_test.capture('already-added-conflict',group_test.request(151,'add'));
reset role;
-- Ordinary joined members may leave, but cannot manage any group metadata.
select set_config('request.jwt.claim.sub',message_send_test.id(2)::text,false);
set role authenticated;
select group_test.denied(group_test.request(160,'create'),'42501');
select group_test.denied((select request from group_test.cases where name='create'),'42501');
select group_test.capture('member-leave',group_test.request(161,'leave'));
reset role;
select set_config('request.jwt.claim.sub',message_send_test.id(1)::text,false);
set role authenticated;
select group_test.capture('manager-readd',group_test.request(162,'add'));
reset role;
select set_config('request.jwt.claim.sub',message_send_test.id(2)::text,false);
set role authenticated;
do $$declare saved record;begin select * into saved from group_test.cases where name='member-leave';assert public.mobile_apply_group_channel(saved.request)=saved.receipt,'Leave history changed';assert exists(select 1 from public.message_channel_members where channel_id=group_test.channel() and team_member_id=message_send_test.id(12)),'Leave retry deleted manager readd';end$$;
reset role;
select set_config('request.jwt.claim.sub',message_send_test.id(1)::text,false);
set role authenticated;
insert into group_test.pending values('channel-change',group_test.request(172,'add',3)),('target-change',group_test.request(173,'add',3));
reset role;
update public.message_channels set name='Changed group' where id=group_test.channel();
set role authenticated;
select group_test.capture('changed-channel-conflict',(select request from group_test.pending where name='channel-change'));
reset role;
update public.message_channels set name='Choir group' where id=group_test.channel();
update public.team_members set status='inactive' where id=message_send_test.id(13);
set role authenticated;
select group_test.capture('changed-target-conflict',(select request from group_test.pending where name='target-change'));
reset role;
update public.team_members set status='active' where id=message_send_test.id(13);
-- Failure after channel/self join creation rolls everything back.
create function group_test.fail_late() returns trigger language plpgsql as $$begin if new.request_nonce=message_send_test.id(170) then raise exception 'Synthetic group history failure';end if;return new;end$$;
create trigger group_test_late before insert on private.mobile_group_channel_receipts for each row execute function group_test.fail_late();
create table group_test.counts as select(select count(*) from public.message_channels) channels,(select count(*) from public.message_channel_members) members;
set role authenticated;
select group_test.denied(group_test.request(170,'create'),'P0001');
reset role;
do $$begin assert(select channels=(select count(*) from public.message_channels) and members=(select count(*) from public.message_channel_members) from group_test.counts),'Late failure left channel or join';end$$;
drop trigger group_test_late on private.mobile_group_channel_receipts;
-- Race adds the unjoined admin3: owner-add and explicit admin self-join.

